import { useState, useMemo } from 'react'

const REBAR_KS = [
  { name: 'D10', d: 10,  area: 71.3,  area_in2: 0.1105 },
  { name: 'D13', d: 13,  area: 126.7, area_in2: 0.1963 },
  { name: 'D16', d: 16,  area: 198.6, area_in2: 0.3079 },
  { name: 'D19', d: 19,  area: 284.9, area_in2: 0.4415 },
  { name: 'D22', d: 22,  area: 387.1, area_in2: 0.5998 },
  { name: 'D25', d: 25,  area: 506.7, area_in2: 0.7854 },
  { name: 'D29', d: 28.6,area: 642.4, area_in2: 0.9954 },
  { name: 'D32', d: 31.8,area: 794.2, area_in2: 1.2305 },
  { name: 'D35', d: 34.9,area: 956.6, area_in2: 1.4824 },
  { name: 'D38', d: 38.1,area: 1140,  area_in2: 1.7671 },
]

// KDS 14 20 50 기준 이형철근 (SD 등급별)
const KDS_GRADES = [
  { grade: 'SD300',  fy: 300,  fck_min: 21 },
  { grade: 'SD350',  fy: 350,  fck_min: 21 },
  { grade: 'SD400',  fy: 400,  fck_min: 21 },
  { grade: 'SD500',  fy: 500,  fck_min: 24 },
  { grade: 'SD600',  fy: 600,  fck_min: 27 },
]

// ASTM A615 / A706 등급
const ACI_GRADES = [
  { grade: 'Grade 40 (A615)', fy_ksi: 40,  fy_mpa: 276 },
  { grade: 'Grade 60 (A615)', fy_ksi: 60,  fy_mpa: 414 },
  { grade: 'Grade 75 (A615)', fy_ksi: 75,  fy_mpa: 517 },
  { grade: 'Grade 60 (A706)', fy_ksi: 60,  fy_mpa: 414 },
  { grade: 'Grade 80 (A706)', fy_ksi: 80,  fy_mpa: 552 },
]

// ASTM 치수 (based on equivalent ASTM bar sizes)
const REBAR_ASTM = [
  { name: '#3',  d_in: 0.375, d_mm: 9.5,  area_in2: 0.11,  area_mm2: 71  },
  { name: '#4',  d_in: 0.500, d_mm: 12.7, area_in2: 0.20,  area_mm2: 129 },
  { name: '#5',  d_in: 0.625, d_mm: 15.9, area_in2: 0.31,  area_mm2: 200 },
  { name: '#6',  d_in: 0.750, d_mm: 19.1, area_in2: 0.44,  area_mm2: 284 },
  { name: '#7',  d_in: 0.875, d_mm: 22.2, area_in2: 0.60,  area_mm2: 387 },
  { name: '#8',  d_in: 1.000, d_mm: 25.4, area_in2: 0.79,  area_mm2: 510 },
  { name: '#9',  d_in: 1.128, d_mm: 28.7, area_in2: 1.00,  area_mm2: 645 },
  { name: '#10', d_in: 1.270, d_mm: 32.3, area_in2: 1.27,  area_mm2: 819 },
  { name: '#11', d_in: 1.410, d_mm: 35.8, area_in2: 1.56,  area_mm2: 1006},
]

export default function RebarArea() {
  const [tab, setTab] = useState('kds')   // 'kds' | 'aci'

  // KDS state
  const [barKS,   setBarKS]   = useState('D13')
  const [countKS, setCountKS] = useState('4')
  const [spacingKS, setSpacingKS] = useState('150')

  // ACI state
  const [barUS,   setBarUS]   = useState('#5')
  const [countUS, setCountUS] = useState('4')
  const [spacingUS, setSpacingUS] = useState('6')

  const selKS   = REBAR_KS.find(b => b.name === barKS)
  const selUS   = REBAR_ASTM.find(b => b.name === barUS)

  const totalKS   = (selKS?.area ?? 0) * (parseInt(countKS) || 0)
  const areaPerMKS = selKS ? ((selKS.area / parseFloat(spacingKS)) * 1000).toFixed(0) : 0

  const totalUS    = (selUS?.area_in2 ?? 0) * (parseInt(countUS) || 0)
  const areaPerFtUS = selUS ? ((selUS.area_in2 / parseFloat(spacingUS)) * 12).toFixed(3) : 0

  return (
    <div>
      <h3 style={titleStyle}>REBAR AREA</h3>

      {/* Tab selector */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 20 }}>
        {[{ id: 'kds', label: '🇰🇷 KDS (KS)' }, { id: 'aci', label: '🇺🇸 ACI (ASTM)' }].map(t => (
          <button key={t.id} onClick={() => setTab(t.id)} style={{
            padding: '6px 18px', borderRadius: 6, fontSize: 12, fontWeight: 600, cursor: 'pointer',
            border: '1px solid var(--bd-subtle)',
            background: tab === t.id ? 'var(--ac-main)' : 'var(--bg-card)',
            color: tab === t.id ? '#000' : 'var(--tx-secondary)',
          }}>{t.label}</button>
        ))}
      </div>

      {tab === 'kds' && (
        <>
          <p style={descStyle}>KDS 14 20 50 — Deformed Bars KS D 3504</p>
          <div className="grid md:grid-cols-2 gap-8" style={{ marginBottom: 24 }}>
            {/* Count calculation */}
            <div style={card}>
              <h4 style={subHead}>Bar Count — Area Calculation</h4>
              <Row label="Bar Type">
                <select value={barKS} onChange={e => setBarKS(e.target.value)} style={selectStyle}>
                  {REBAR_KS.map(b => <option key={b.name} value={b.name}>{b.name}</option>)}
                </select>
              </Row>
              <Row label="Count">
                <input type="number" value={countKS} onChange={e => setCountKS(e.target.value)} style={inputStyle} />
              </Row>
              <div style={resultBox}>
                <p>1 bar = <Val>{selKS?.area ?? 0} mm²</Val></p>
                <p style={{ marginTop: 6 }}>Total As = <Val>{totalKS.toFixed(1)} mm²</Val></p>
              </div>
            </div>

            {/* Spacing calculation */}
            <div style={card}>
              <h4 style={subHead}>Bar Spacing — As per Meter</h4>
              <Row label="Bar Type">
                <select value={barKS} onChange={e => setBarKS(e.target.value)} style={selectStyle}>
                  {REBAR_KS.map(b => <option key={b.name} value={b.name}>{b.name}</option>)}
                </select>
              </Row>
              <Row label="Spacing (mm)">
                <input type="number" value={spacingKS} onChange={e => setSpacingKS(e.target.value)} style={inputStyle} />
              </Row>
              <div style={resultBox}>
                <p>As = <Val>{areaPerMKS} mm²/m</Val></p>
                <p style={{ fontSize: 12, color: 'var(--tx-muted)', marginTop: 4 }}>{barKS}@{spacingKS}</p>
              </div>
            </div>
          </div>

          {/* KS Bar Size Table */}
          <h4 style={{ ...subHead, marginBottom: 10 }}>KS Deformed Bar Size Table (KS D 3504)</h4>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr>
                  {['Size', 'Nom. dia (mm)', 'Area (mm²)', 'Area (in²)', 'Mass (kg/m)'].map(h => (
                    <th key={h} style={th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {REBAR_KS.map(b => (
                  <tr key={b.name} style={{ background: b.name === barKS ? 'var(--bg-active)' : 'transparent', cursor: 'pointer' }}
                    onClick={() => setBarKS(b.name)}>
                    <td style={{ ...td, fontWeight: 700, color: 'var(--ac-main)' }}>{b.name}</td>
                    <td style={td}>{b.d}</td>
                    <td style={{ ...td, color: 'var(--val-pos)', fontWeight: 700 }}>{b.area}</td>
                    <td style={{ ...td, color: 'var(--tx-secondary)' }}>{b.area_in2.toFixed(4)}</td>
                    <td style={td}>{(b.area * 7.85e-3).toFixed(3)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* KDS Grade Table */}
          <h4 style={{ ...subHead, marginTop: 24, marginBottom: 10 }}>KDS Steel Grade Classification</h4>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr>
                  {['Grade', 'fy (MPa)', 'fu (MPa)', 'Standard', 'Note'].map(h => (
                    <th key={h} style={th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[
                  { grade:'SD300', fy:300, fu:440, std:'KS D 3504', note:'General RC' },
                  { grade:'SD350', fy:350, fu:490, std:'KS D 3504', note:'General RC' },
                  { grade:'SD400', fy:400, fu:560, std:'KS D 3504', note:'General RC (typical)' },
                  { grade:'SD500', fy:500, fu:620, std:'KS D 3504', note:'High Strength' },
                  { grade:'SD600', fy:600, fu:710, std:'KS D 3504', note:'High Strength' },
                ].map(r => (
                  <tr key={r.grade}>
                    <td style={{ ...td, fontWeight: 700, color: 'var(--ac-main)' }}>{r.grade}</td>
                    <td style={{ ...td, color: 'var(--val-pos)', fontWeight: 700 }}>{r.fy}</td>
                    <td style={td}>{r.fu}</td>
                    <td style={td}>{r.std}</td>
                    <td style={{ ...td, color: 'var(--tx-secondary)' }}>{r.note}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}

      {tab === 'aci' && (
        <>
          <p style={descStyle}>ACI 318-19 — ASTM A615 / A706 Deformed Bars</p>
          <div className="grid md:grid-cols-2 gap-8" style={{ marginBottom: 24 }}>
            {/* 개수 계산 */}
            <div style={card}>
              <h4 style={subHead}>Bar Count — Area Calculation</h4>
              <Row label="Bar Size">
                <select value={barUS} onChange={e => setBarUS(e.target.value)} style={selectStyle}>
                  {REBAR_ASTM.map(b => <option key={b.name} value={b.name}>{b.name}</option>)}
                </select>
              </Row>
              <Row label="Count">
                <input type="number" value={countUS} onChange={e => setCountUS(e.target.value)} style={inputStyle} />
              </Row>
              <div style={resultBox}>
                <p>1 bar = <Val>{selUS?.area_in2 ?? 0} in²</Val> ({selUS ? (selUS.area_in2 * 645.16).toFixed(0) : 0} mm²)</p>
                <p style={{ marginTop: 6 }}>Total As = <Val>{totalUS.toFixed(3)} in²</Val> ({(totalUS * 645.16).toFixed(0)} mm²)</p>
              </div>
            </div>

            {/* 간격 계산 */}
            <div style={card}>
              <h4 style={subHead}>Bar Spacing — As per Foot</h4>
              <Row label="Bar Size">
                <select value={barUS} onChange={e => setBarUS(e.target.value)} style={selectStyle}>
                  {REBAR_ASTM.map(b => <option key={b.name} value={b.name}>{b.name}</option>)}
                </select>
              </Row>
              <Row label="Spacing (in)">
                <input type="number" value={spacingUS} onChange={e => setSpacingUS(e.target.value)} style={inputStyle} />
              </Row>
              <div style={resultBox}>
                <p>As = <Val>{areaPerFtUS} in²/ft</Val></p>
                <p style={{ fontSize: 12, color: 'var(--tx-muted)', marginTop: 4 }}>
                  {barUS}@{spacingUS}" ({(parseFloat(spacingUS)*25.4).toFixed(0)} mm)
                </p>
              </div>
            </div>
          </div>

          {/* ASTM 규격표 */}
          <h4 style={{ ...subHead, marginBottom: 10 }}>ASTM Bar Size Table</h4>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr>
                  {['Bar', 'dia (in)', 'dia (mm)', 'Area (in²)', 'Area (mm²)', 'Mass (lb/ft)'].map(h => (
                    <th key={h} style={th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {REBAR_ASTM.map(b => (
                  <tr key={b.name} style={{ background: b.name === barUS ? 'var(--bg-active)' : 'transparent', cursor: 'pointer' }}
                    onClick={() => setBarUS(b.name)}>
                    <td style={{ ...td, fontWeight: 700, color: 'var(--ac-main)' }}>{b.name}</td>
                    <td style={td}>{b.d_in.toFixed(3)}</td>
                    <td style={td}>{b.d_mm}</td>
                    <td style={{ ...td, color: 'var(--val-pos)', fontWeight: 700 }}>{b.area_in2.toFixed(2)}</td>
                    <td style={td}>{b.area_mm2}</td>
                    <td style={td}>{(b.area_in2 * 3.4).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* ACI 등급표 */}
          <h4 style={{ ...subHead, marginTop: 24, marginBottom: 10 }}>ASTM Steel Grade Table</h4>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
              <thead>
                <tr>
                  {['Grade', 'fy (ksi)', 'fy (MPa)', 'fu (ksi)', 'Standard', 'Note'].map(h => (
                    <th key={h} style={th}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[
                  { grade:'Grade 40', fy_ksi:40, fy_mpa:276, fu_ksi:60, std:'A615', note:'Light structures' },
                  { grade:'Grade 60', fy_ksi:60, fy_mpa:414, fu_ksi:90, std:'A615', note:'General RC (typical)' },
                  { grade:'Grade 75', fy_ksi:75, fy_mpa:517, fu_ksi:100,std:'A615', note:'High Strength' },
                  { grade:'Grade 60', fy_ksi:60, fy_mpa:414, fu_ksi:80, std:'A706', note:'Seismic' },
                  { grade:'Grade 80', fy_ksi:80, fy_mpa:552, fu_ksi:100,std:'A706', note:'Seismic High Strength' },
                ].map((r, i) => (
                  <tr key={i}>
                    <td style={{ ...td, fontWeight: 700, color: 'var(--ac-main)' }}>{r.grade}</td>
                    <td style={{ ...td, color: 'var(--val-pos)', fontWeight: 700 }}>{r.fy_ksi}</td>
                    <td style={td}>{r.fy_mpa}</td>
                    <td style={td}>{r.fu_ksi}</td>
                    <td style={td}>{r.std}</td>
                    <td style={{ ...td, color: 'var(--tx-secondary)' }}>{r.note}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  )
}

function Row({ label, children }) {
  return (
    <div style={{ marginBottom: 12 }}>
      <label style={labelStyle}>{label}</label>
      {children}
    </div>
  )
}

const titleStyle  = { fontSize: '1.3rem', fontWeight: 700, marginBottom: 8, color: 'var(--tx-primary)', paddingBottom: 10, borderBottom: '1px solid var(--bd-subtle)' }
const descStyle   = { marginBottom: 20, color: 'var(--tx-secondary)', fontSize: 13 }
const subHead     = { fontSize: 13, fontWeight: 700, marginBottom: 14, color: 'var(--ac-main)' }
const labelStyle  = { display: 'block', fontSize: 12, fontWeight: 500, color: 'var(--tx-secondary)', marginBottom: 4 }
const card        = { background: 'var(--bg-card)', border: '1px solid var(--bd-accent)', borderRadius: 10, padding: 20 }
const selectStyle = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 6, color: 'var(--tx-primary)', padding: '6px 8px', width: '100%', fontSize: 13 }
const inputStyle  = { background: 'var(--bg-input)', border: '1px solid var(--bd-subtle)', borderRadius: 6, color: 'var(--tx-primary)', padding: '6px 10px', width: '100%', textAlign: 'center', fontSize: 15, fontWeight: 600 }
const resultBox   = { background: 'var(--bg-inset)', border: '1px solid var(--bd-accent)', borderRadius: 8, padding: 14, marginTop: 12, fontSize: 15 }
const th = { background: 'var(--bg-inset)', color: 'var(--ac-main)', fontWeight: 600, padding: '9px 12px', textAlign: 'left', borderBottom: '2px solid var(--bd-accent)' }
const td = { padding: '8px 12px', borderBottom: '1px solid var(--bd-subtle)', color: 'var(--tx-primary)' }

function Val({ children }) {
  return <span style={{ fontWeight: 700, color: 'var(--val-pos)' }}>{children}</span>
}
